from typing import List, Mapping, Optional, Tuple
import heapq

def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in adj: raise KeyError(src)
    if dst not in adj: raise KeyError(dst)
    if src == dst: return (0, [src])
    def neg_p(p: List[str]) -> Tuple[int, ...]:
        return tuple(-ord(c) for s in p for c in s)
    pq = [(0, neg_p([src]), [src])]
    best = {src: (0, [src])}
    while pq:
        d, _, path = heapq.heappop(pq)
        u = path[-1]
        if d > best[u][0] or (d == best[u][0] and path < best[u][1]): continue
        if u == dst: continue
        for v, w in adj.get(u, {}).items():
            nd, np = d + w, path + [v]
            if v not in best or nd < best[v][0] or (nd == best[v][0] and np > best[v][1]):
                best[v] = (nd, np)
                heapq.heappush(pq, (nd, neg_p(np), np))
    return (best[dst][0], best[dst][1]) if dst in best else None
"}}

